import type { BlogArticleFaq } from '../../../types/blog';

export const BODY: string = "\n<p>কিছু আপলোড ফরম খুব কড়া হয়। তারা 50KB-এর নিচে ছবি চায়, আর এর চেয়ে বড় ফাইল হলে ছবি যত ভালোই হোক না কেন, ফরমটি তা ফিরিয়ে দেয়।</p>\n<p>আজকের ফোনের ছবির পাশে এই সীমাটি খুব ছোট মনে হয়। একটি সাধারণ ছবিই 4MB বা তার বেশি হতে পারে, অর্থাৎ সীমার চেয়ে আশি গুণ বড়।</p>\n<p>এই গাইডে আপনি জানবেন কীভাবে ছবি সঠিকভাবে 50KB-তে কমপ্রেস করবেন। সীমাটির মানে কী, কোন ফরম্যাট এতে সবচেয়ে ভালো কাজ করে, আর ছবিকে ঝাপসা না করে কীভাবে লক্ষ্যে পৌঁছাবেন — সবই এখানে আছে।</p>\n<h2 id=\"what-does-50kb-mean\">50KB আসলে কী বোঝায়?</h2>\n<p>কিলোবাইট হলো ফাইলের আকার মাপার একক। পঞ্চাশ কিলোবাইট মানে প্রায় 51,200 বাইট, যা আজকের হিসাবে খুবই ছোট পরিমাণ ডেটা।</p>\n<p>তুলনা করলে, ফোনের একটি সাধারণ ছবি 2MB থেকে 6MB-এর মধ্যে হয়। তাই অনেক সময় মূল ফাইলের 98 শতাংশেরও বেশি ওজন কমাতে হয়।</p>\n<p>এই সংখ্যাটি একটি সর্বোচ্চ সীমা, হুবহু মেলানোর লক্ষ্য নয়। 49KB-এর ফাইল পাস করে, আর 51KB-এর ফাইল ফেল করে, যদিও চোখে দুটির পার্থক্য ধরা পড়ে না।</p>\n<p>পোর্টালগুলো বাইটের সংখ্যা দেখে, ছবির চেহারা দেখে নয়। তাই আন্দাজে কাজ হয় না, আর এমন টুল দরকার যা সীমার একটু নিচে লক্ষ্য করে।</p>\n<h2 id=\"why-portals-ask-for-50kb\">পোর্টালগুলো 50KB চায় কেন?</h2>\n<p>সরকারি ফরম, পরীক্ষার বোর্ড আর চাকরির পোর্টাল লাখ লাখ আপলোড সংরক্ষণ করে। ছোট ফাইল তাদের ডেটাবেস দ্রুত রাখে আর স্টোরেজের খরচ কমায়।</p>\n<p>পাসপোর্টের পোর্টালের 12 মেগাপিক্সেলের প্রতিকৃতি দরকার নেই। তাদের দরকার পরিষ্কার মুখ, সঠিক মাপ, আর এমন ফাইল যা তাদের সিস্টেম মুহূর্তে প্রক্রিয়া করতে পারে।</p>\n<p>নির্দিষ্ট সীমা সবার জন্য সমান সুযোগ রাখে। প্রত্যেক আবেদনকারী প্রায় একই ওজনের ফাইল আপলোড করে, তাই ভারী ফাইল দিয়ে কেউ বাড়তি সুবিধা পায় না।</p>\n<p>কিছু পুরোনো সিস্টেম তৈরি হয়েছিল যখন ইন্টারনেটের গতি ছিল ব্যয়বহুল। ক্যামেরা অনেক উন্নত হলেও তাদের সীমা আর বদলায়নি।</p>\n<h2 id=\"how-compression-reaches-50kb\">কমপ্রেশন কীভাবে 50KB-তে পৌঁছায়?</h2>\n<p>কমপ্রেশন এমন ডেটা সরিয়ে দেয় যা চোখ প্রায় খেয়ালই করে না। রঙের সূক্ষ্ম পরিবর্তন মসৃণ করে, ছোট শব্দ দূর করে আর ব্যস্ত টেক্সচার সহজ করে দেয়।</p>\n<p>কোয়ালিটি সেটিং ঠিক করে এই ছাঁটাই কতটা কঠোর হবে। কোয়ালিটি কমালে ফাইল ছোট হয়, কিন্তু ক্ষতিও চোখে বেশি পড়ে।</p>\n<p>শুধু কোয়ালিটি কমিয়ে লক্ষ্য না মিললে টুল পিক্সেলের মাপ ছোট করে। ছোট ছবি বর্ণনা করতে কম ডেটা লাগে, তাই ফাইলও ছোট হয়।</p>\n<p>ভালো কমপ্রেসর প্রথমে পূর্ণ আকারে কোয়ালিটি দিয়ে চেষ্টা করে। সেটা না পারলেই ধাপে ধাপে মাপ কমায়, খুব সাবধানে।</p>\n<h2 id=\"binary-quality-search\">বাইনারি কোয়ালিটি সার্চ, সহজ ভাষায়</h2>\n<p>CompressMyPic-এর 50KB টুল কোয়ালিটির সংখ্যা আন্দাজ করে না। এটি বাইনারি সার্চ চালায়, অর্থাৎ বিভিন্ন কোয়ালিটি পরীক্ষা করে সবচেয়ে বেশি কোয়ালিটি খুঁজে নেয় যা 50KB-এর নিচে থাকে।</p>\n<p>এটাকে 1 থেকে 100-এর মধ্যে সংখ্যা খোঁজার মতো ভাবুন। প্রতিটি পরীক্ষায় বাকি পরিসর অর্ধেক হয়ে যায়, তাই উত্তর খুব দ্রুত মিলে যায়।</p>\n<p>এটা গুরুত্বপূর্ণ, কারণ আপনার ছবির সেরা কোয়ালিটি 50 বা 70 নয়, 63 শতাংশও হতে পারে। সার্চ সেই সঠিক বিন্দুটিই খুঁজে বের করে।</p>\n<p>ফলে আপনি পান আপনার ছবির সবচেয়ে পরিষ্কার সংস্করণ, যা দরকারি আকারের মধ্যে থাকে — নিরাপদ কিন্তু অযথা নরম সংস্করণ নয়।</p>\n<p>বাইনারি সার্চ একবারে একটি কোয়ালিটি মান পরীক্ষা করে না। এটি প্রথমে মাঝামাঝি একটি মান নেয়, ফলের আকার দেখে, তারপর সিদ্ধান্ত নেয় পরের চেষ্টা উপরে যাবে না নিচে। এইভাবে প্রতিটি ধাপে সম্ভাব্য সীমা অর্ধেক হয়ে যায়।</p>\n<p>সাধারণত সাত থেকে আটটি চেষ্টায় সার্চ সেরা মানটি খুঁজে পায়। একশোটি মান একে একে পরীক্ষা করার চেয়ে এটি অনেক দ্রুত। আপনার ফোনে পুরো প্রক্রিয়াটি মাত্র কয়েক সেকেন্ডে শেষ হয়।</p>\n<p>সার্চ সবসময় সীমার ঠিক নিচে থামে, যেমন ৪৯.২KB বা ৪৯.৮KB। এই ছোট ব্যবধান ইচ্ছাকৃত। পোর্টালগুলো বাইটে মাপে, আর গোল করার পার্থক্যে একটি ফাইল এক ডিভাইসে পাস করে অন্য ডিভাইসে ফেল করতে পারে।</p>\n<p>ছবির ধরন সার্চের ফল বদলে দেয়। আকাশের মতো মসৃণ অংশ দ্রুত ছোট হয়, আর গাছের পাতা বা কাপড়ের বুননের মতো জটিল অংশে বেশি কোয়ালিটি দরকার হয়। তাই একই সেটিং দুটি ছবিতে ভিন্ন ফল দেয়।</p>\n<p>কিছু টুল সার্চের সময় ছবির একটি ছোট অংশ আগে পরীক্ষা করে। এতে সময় বাঁচে, তবে চূড়ান্ত ফল পুরো ছবিতেই যাচাই করা হয়। প্রিভিউ দেখে নেওয়া তাই এখনও জরুরি।</p>\n<p>সার্চ যদি লক্ষ্য না পায়, টুলটি নিজে থেকে মাপ কমানোর প্রস্তাব দেয়। পোর্টালের নিয়মে নির্দিষ্ট মাপ না থাকলে এই প্রস্তাব মেনে নেওয়া নিরাপদ। মাপ কমালে আকার দ্রুত কমে যায়।</p>\n<p>পুরোনো ছবি বা বারবার সংরক্ষিত JPG ফাইলে সার্চ কঠিন হয়। এসব ফাইলে ইতিমধ্যে অনেক তথ্য হারিয়ে গেছে, তাই কোয়ালিটি কমালেও আকার সহজে কমে না। মূল কপি থাকলে সেটি ব্যবহার করুন।</p>\n<p>ব্যাচে কাজ করার সময় প্রতিটি ছবির জন্য আলাদা সার্চ চলে। একটি ছবি সহজে ৫০KB-তে আসতে পারে, অন্যটি মাপ কমানো ছাড়া আসে না। প্রতিটি ফলের আকার আলাদাভাবে পরীক্ষা করুন।</p>\n<p>সার্চ শেষে ডাউনলোডের আগে ফাইলের আকার বাইটে দেখে নিন। ডিভাইসের দেখানো গোল করা সংখ্যা আর পোর্টালের মাপা সংখ্যা এক নাও হতে পারে। ৪৯KB দেখালে আপনি নিরাপদে আছেন।</p>\n<h2 id=\"best-format-for-50kb\">50KB-তে কোন ফরম্যাট সবচেয়ে ভালো?</h2>\n<p>মানুষের ছবির ক্ষেত্রে 50KB-তে JPG সাধারণত সেরা পছন্দ। এত ছোট আকারে ত্বকের মসৃণ রং আর গ্রেডিয়েন্ট PNG-এর চেয়ে অনেক ভালোভাবে সামলায়।</p>\n<p>WebP অনেক সময় JPG-কে সামান্য ব্যবধানে ছাড়িয়ে যায়। একই ফাইল ওজনে এর প্রান্ত একটু পরিষ্কার থাকে, যদিও কিছু পুরোনো পোর্টাল এটি নেয় না।</p>\n<p>এই আকারে বেশিরভাগ ছবির জন্য PNG ভুল পছন্দ। এটি ছবি কোনো ক্ষতি ছাড়াই সংরক্ষণ করে, তাই বিস্তারিত ছবি ছোট মাপেও 50KB-এর অনেক উপরে থেকে যেতে পারে।</p>\n<p>PNG শুধু তখনই ব্যবহার করুন যখন পরিষ্কার লেখা, সমতল গ্রাফিক্স বা স্বচ্ছতা দরকার। প্রতিকৃতি বা স্ক্যান করা নথির জন্য JPG বা WebP ভালো কাজ করবে।</p>\n<h2 id=\"quality-at-50kb\">50KB-তে কেমন কোয়ালিটি আশা করা যায়?</h2>\n<p>সত্যি কথা বলতে, 50KB একটি আপস। মুখ চেনা যাবে, নথি পড়া যাবে, কিন্তু সূক্ষ্ম বিবরণ কিছুটা নরম হয়ে যাবে।</p>\n<p>প্রতিকৃতি সবচেয়ে ভালো টিকে থাকে, কারণ মুখে অনেক মসৃণ অংশ থাকে। চুল আর কাপড়ের টেক্সচার কিছুটা হারালেও সামগ্রিক ছবি পরিষ্কার দেখায়।</p>\n<p>বিস্তারিত প্রাকৃতিক দৃশ্য আর ব্যস্ত স্ক্রিনশট বেশি ক্ষতিগ্রস্ত হয়। স্ক্রিনশটের ছোট লেখা ঝাপসা হতে পারে, তাই মাপ যতটা সম্ভব বড় রাখুন।</p>\n<p>কৌশল হলো গুরুত্বপূর্ণ অংশগুলো রক্ষা করা। পাসপোর্ট ছবিতে পরিষ্কার মুখ দরকার, পরিষ্কার ব্যাকগ্রাউন্ড নয়, আর কমপ্রেশন স্বাভাবিকভাবেই মসৃণ অংশকে প্রাধান্য দেয়।</p>\n<h2 id=\"common-uses-for-50kb\">50KB ছবি আসলে কোথায় ব্যবহার হয়?</h2>\n<p>পাসপোর্ট ও ভিসার আবেদনই সবচেয়ে পরিচিত উদাহরণ। অনেক পোর্টাল ছবি 50KB-এ সীমাবদ্ধ রাখে আর পিক্সেলের সঠিক মাপও চায়।</p>\n<p>পরীক্ষার রেজিস্ট্রেশন ফরম ছবি ও স্বাক্ষরের জন্য একই সীমা ব্যবহার করে। স্ক্যান করা স্বাক্ষর প্রায় পুরোটাই সাদা জায়গা, তাই এটি খুব ভালোভাবে কমপ্রেস হয়।</p>\n<p>কিছু চাকরির পোর্টাল আর বিশ্ববিদ্যালয়ের ভর্তি ব্যবস্থাও প্রোফাইল ছবি 50KB-এ সীমাবদ্ধ রাখে। এই আকারের পরিষ্কার ছবি যেকোনো সংযোগে মুহূর্তে লোড হয়।</p>\n<p>অ্যাভাটার আর ফোরামের প্রোফাইল ছবিও প্রায় 50KB-এর আশেপাশে থাকে। শত শত অ্যাভাটার একসঙ্গে দেখালে পাতা হালকা রাখতে এই সীমা কাজ করে।</p>\n<p>৫০KB ছবির সবচেয়ে সাধারণ ব্যবহার পাসপোর্ট আবেদন। প্রায় সব দেশের পাসপোর্ট পোর্টাল ৫০KB-এর নিচে ছবি চায়। আবেদনের দিন ছবি তৈরি থাকলে লাইনে দাঁড়িয়ে অপেক্ষা করতে হয় না।</p>\n<p>পরীক্ষার ফরমেও ৫০KB ছবি লাগে। ভর্তি পরীক্ষা, চাকরির পরীক্ষা আর লাইসেন্সের আবেদনে ছবির সীমা ৫০KB হয়। ফরম জমা দেওয়ার শেষ দিনে ছবি নিয়ে ঝামেলা এড়াতে আগেই তৈরি করে রাখুন।</p>\n<p>স্কুলের ভর্তি ফরমে শিশুর ছবি ৫০KB-তে চাওয়া হয়। শিশুর ছবি তোলা কঠিন, তাই একবার ভালো ছবি তুলে ৫০KB-তে করে সংরক্ষণ করুন। প্রতিটি ভর্তি ফরমে একই ছবি ব্যবহার করা যায়।</p>\n<p>ব্যাংকের KYC ফরমে ছবি ৫০KB-তে দিতে হয়। ব্যাংকের পোর্টাল বড় ফাইল নেয় না। ছবি তৈরি থাকলে অ্যাকাউন্ট খোলা দ্রুত হয়।</p>\n<p>ভিসার আবেদনে ছবির সীমা অনেক সময় ৫০KB হয়। ভিসার ছবিতে মুখের মাপের নিয়মও থাকে। ছবি ৫০KB-তে করার সময় মুখের মাপ ঠিক আছে কিনা দেখুন।</p>\n<p>অনলাইন ফরমে স্বাক্ষরের ছবিও ৫০KB-তে লাগে। স্বাক্ষর সাদা কাগজে লিখে স্ক্যান করলে ফাইল এমনিতেই ছোট হয়। স্বাক্ষরের জন্য ৫০KB সীমা পার হওয়া কঠিন।</p>\n<p>৫০KB ছবি মেসেজিং অ্যাপে পাঠাতে সুবিধা। ধীর ইন্টারনেটেও ছবি দ্রুত যায়। গ্রামে থাকা আত্মীয়কে ছবি পাঠাতে ৫০KB ভালো।</p>\n<p>৫০KB ছবি ওয়েবসাইটের প্রোফাইল ছবি হিসেবে ব্যবহার করা যায়। ছোট প্রোফাইল ছবিতে মানের পার্থক্য ধরা পড়ে না। পাতা দ্রুত লোড হয়।</p>\n<p>৫০KB ছবি ইমেইলের স্বাক্ষরে ব্যবহার করা যায়। ইমেইলের সঙ্গে ছোট ছবি যুক্ত করলে ইমেইল ভারী হয় না। প্রাপক দ্রুত ইমেইল খুলতে পারেন।</p>\n<h2 id=\"how-to-use-the-tool\">50KB-তে ছবি কমপ্রেস করার টুলটি কীভাবে ব্যবহার করবেন</h2>\n<p>ব্রাউজারে <a href=\"/bn/image-50kb-te-compress-korun\">50KB-তে ছবি কমপ্রেস করার টুলটি</a> খুলুন। সব কাজ আপনার ডিভাইসেই হয়, তাই আপনার ছবি কোনো সার্ভারে আপলোড হয় না।</p>\n<p>আপলোড এলাকায় ছবিটি ছেড়ে দিন। JPG, PNG, WebP আর HEIC ফাইল নেওয়া হয়, আর 25MB পর্যন্ত ইনপুট গ্রহণ করা হয়।</p>\n<p>টুলটি স্বয়ংক্রিয়ভাবে কোয়ালিটি সার্চ চালিয়ে ফল দেখায়। 50KB-এর নিচে ব্যাজটি খুঁজুন, যা নিশ্চিত করে ফাইলটি সীমা পার করেছে।</p>\n<p>ডাউনলোডের আগে ছবিটি দেখে নিন। মুখ বা লেখার উপর জুম করে দেখুন গুরুত্বপূর্ণ কিছু নষ্ট হয়নি তো।</p>\n<ol>\n<li>50KB টুলে আপনার ছবি আপলোড করুন।</li>\n<li>বাইনারি সার্চকে সবচেয়ে ভালো কোয়ালিটি খুঁজতে দিন যা এতে আঁটে।</li>\n<li>ফল দেখে মুখ আর লেখা কাছ থেকে পরীক্ষা করুন।</li>\n<li>ফাইলটি ডাউনলোড করে পোর্টালে আপলোড করুন।</li>\n</ol>\n<h2 id=\"mistakes-to-avoid\">যেসব ভুলে 50KB আরও কঠিন হয়ে যায়</h2>\n<p>সবচেয়ে সাধারণ ভুল হলো মূল ছবির বদলে স্ক্রিনশট দিয়ে শুরু করা। স্ক্রিনশটে বাড়তি শব্দ থাকে যা মূল্যবান কিলোবাইট নষ্ট করে।</p>\n<p>আরেকটি ভুল হলো ছবির জন্য ফরম্যাট PNG-তে আটকে রাখা। PNG যথেষ্ট ওজন কমাতে পারে না, আর টুল সতর্ক করবে যে লক্ষ্য মেলেনি।</p>\n<p>অনেকেই পোর্টালের নিয়ম দেখতে ভুলে যান। পোর্টাল 600 বাই 600 পিক্সেল চাইলে আর WebP না নিলে, যত বুদ্ধিমান কমপ্রেশনই হোক, কাজ হবে না।</p>\n<p>সবশেষে, ইতিমধ্যে কমপ্রেস করা ফাইল আবার কমপ্রেস করবেন না। প্রতিটি রাউন্ডে ক্ষতি বাড়ে, তাই সবসময় সর্বোচ্চ মানের মূল ছবি দিয়ে শুরু করুন।</p>\n<h2 id=\"50kb-vs-other-sizes\">50KB বনাম 100KB বনাম 200KB: দ্রুত তুলনা</h2>\n<p>100KB-তে প্রতিকৃতি 50KB-এর চেয়ে লক্ষণীয়ভাবে বেশি বিবরণ ধরে রাখে। চুল, চশমা আর কাপড়ের প্রান্ত সবই পরিষ্কার দেখায়।</p>\n<p>200KB-তে বেশিরভাগ ছবি সাধারণ দেখার আকারে মূল ছবির মতোই দেখায়। তাই ব্লগ আর দোকানগুলো এটি পছন্দ করে।</p>\n<p>বিনিময়টি সহজ: ছোট ফাইল কঠোর পোর্টালে পাস করে, আর বড় ফাইল দেখতে ভালো লাগে। আপনার পোর্টাল যত বড় আকার নেয়, সেটাই বেছে নিন।</p>\n<p>পোর্টাল 100KB নিলে অকারণে 50KB-তে চাপবেন না। সিদ্ধান্ত নেওয়ার আগে আমাদের তুলনাটি পড়ুন: <a href=\"/bn/blog/image-size-50kb-vs-100kb-vs-200kb\">50KB বনাম 100KB বনাম 200KB: কোন আকার বেছে নেবেন?</a>।</p>\n<h2 id=\"privacy-and-safety\">গোপনীয়তা: আপনার ছবির কী হয়?</h2>\n<p>কমপ্রেশন পুরোপুরি আপনার ব্রাউজারেই হয়। আপনার পরিচয়পত্রের ছবি কখনো কোনো সার্ভারে যায় না, যা পাসপোর্ট ছবির ক্ষেত্রে খুব গুরুত্বপূর্ণ।</p>\n<p>টুলটি আপনার ছবি থেকে লুকানো অবস্থানের তথ্যও সরিয়ে দেয়। কমপ্রেশনের সময় ক্যামেরার GPS ট্যাগ মুছে যায়, তাই ডাউনলোড করা ফাইলে ছবিটি কোথায় তোলা হয়েছিল তার কোনো রেকর্ড থাকে না।</p>\n<p>পরিচয়পত্রের নথির জন্য এটি আসল সুবিধা। পাসপোর্ট ছবিতে আপনার ফোন বা বাড়ি সম্পর্কে মেটাডেটা থাকা উচিত নয়।</p>\n<p>জমা দেওয়ার আগে ডাউনলোড করা ফাইলটি সবসময় একবার দেখে নিন। একবার খুলে মুখ পরিষ্কার দেখাচ্ছে কি না নিশ্চিত করুন, তারপর পোর্টালে আপলোড করুন।</p>\n<h2 id=\"exam-forms-at-50kb\">পরীক্ষা ও ভর্তির ফরমে 50KB</h2>\n<p>পরীক্ষার বোর্ডগুলো 50KB সীমার সবচেয়ে কঠোর ব্যবহারকারীদের মধ্যে আছে। তারা ছবি ও স্বাক্ষর দুটোই 50KB-এর নিচে আর নির্দিষ্ট ফরম্যাটে চায়।</p>\n<p>ছবির নিয়মগুলো সাধারণত কঠিন অংশ। মুখ সামনের দিকে থাকতে হবে, ব্যাকগ্রাউন্ড সাধারণ হতে হবে, আর মাপ হুবহু হতে হবে, অনেক সময় 200 বাই 230 পিক্সেল বা কাছাকাছি।</p>\n<p>স্বাক্ষর সহজ। স্বাক্ষর প্রায় পুরোটাই খালি সাদা জায়গা, তাই কোনো দৃশ্যমান ক্ষতি ছাড়াই এটি 50KB-এর অনেক নিচে কমপ্রেস হয়।</p>\n<p>ফরম খোলার আগেই দুটি ফাইল তৈরি করে রাখুন। সময়সীমার চাপে একটা একটা করে আপলোড করতে গিয়েই ভুল হয়।</p>\n<p>কমপ্রেস করা ফাইলগুলো পরিষ্কার নামে সংরক্ষণ করুন, যেমন exam-photo-50kb.jpg। অ্যাডমিট কার্ড বা কাউন্সেলিং রাউন্ডের জন্য একই ফাইল আবার দরকার হতে পারে।</p>\n<p>পরীক্ষার ফরমে ছবির নিয়ম ফরমের নির্দেশনায় লেখা থাকে। ছবির মাপ, ফরম্যাট আর ফাইলের আকার — তিনটি নিয়মই পড়ুন। একটি নিয়ম না মানলে ফরম বাতিল হতে পারে।</p>\n<p>পরীক্ষার ফরমে ছবি আপলোড করার আগে প্রিভিউ দেখুন। প্রিভিউতে ছবি ঠিকমতো দেখা যাচ্ছে কিনা দেখুন। ছবি উল্টো থাকলে আবার আপলোড করুন।</p>\n<p>পরীক্ষার ফরমে ছবি জমা দেওয়ার শেষ তারিখ মনে রাখুন। শেষ দিনে সার্ভার ধীর হয়। ছবি তৈরি থাকলে শেষ দিনেও জমা দেওয়া যায়।</p>\n<p>পরীক্ষার ফরমে একই ছবি অ্যাডমিট কার্ডেও ব্যবহার হয়। অ্যাডমিট কার্ডের ছবি আর ফরমের ছবি একই হওয়া উচিত। ভিন্ন ছবি হলে পরীক্ষার হলে সমস্যা হতে পারে।</p>\n<p>পরীক্ষার ফরমে ছবির ব্যাকগ্রাউন্ড সাদা রাখুন। রঙিন ব্যাকগ্রাউন্ডের ছবি বাতিল হতে পারে। সাদা দেয়ালের সামনে ছবি তুলুন।</p>\n<p>পরীক্ষার ফরমে ছবির মুখের মাপ দেখুন। মুখ ছবির ৭০ শতাংশ জায়গা নেওয়া উচিত। মুখ ছোট হলে ছবি বাতিল হতে পারে।</p>\n<p>পরীক্ষার ফরমে ছবি জমা দেওয়ার পর নিশ্চিতকরণ পাতাটি সংরক্ষণ করুন। নিশ্চিতকরণ পাতায় ছবি দেখা যায়। ছবি ভুল থাকলে তখনই ধরা পড়ে।</p>\n<p>পরীক্ষার ফরমে ছবি আপলোডের সময় ফাইলের নামে রোল নম্বর লিখুন। নামে রোল নম্বর থাকলে পরে খুঁজে পাওয়া সহজ হয়।</p>\n<p>পরীক্ষার ফরমে ছবি তৈরি করার সময় মূল ছবি সংরক্ষণ করুন। পরে অ্যাডমিট কার্ডে একই ছবি দরকার হতে পারে। মূল থাকলে আবার তৈরি করা যায়।</p>\n<h2 id=\"crop-before-compressing\">আগে ক্রপ করুন, তারপর কমপ্রেস করুন</h2>\n<p>কমপ্রেসের আগে ক্রপ করা 50KB-তে কোয়ালিটি ধরে রাখার সবচেয়ে কার্যকর কৌশল। যত পিক্সেল সরাবেন, কমপ্রেসরের তত কম ডেটা সংরক্ষণ করতে হবে।</p>\n<p>খালি আকাশ, ফাঁকা দেয়াল আর চওড়া মার্জিন কেটে ফেলুন। বিষয়টিকে ফ্রেমে বড় রাখুন আর ব্যাকগ্রাউন্ড কম রাখুন।</p>\n<p>প্রতিকৃতির ক্ষেত্রে মাথা ও কাঁধ পর্যন্ত ক্রপ করুন। মুখ 50KB বাজেটের বেশি অংশ পায়, তাই তা পরিষ্কার থাকে।</p>\n<p>ক্রপটি মূল ফাইলে করুন, ইতিমধ্যে কমপ্রেস করা কপিতে নয়। কমপ্রেসের পর ক্রপ করলে কোয়ালিটি দুবার নষ্ট হয়।</p>\n<p>পোর্টাল নির্দিষ্ট মাপ চাইলে প্রথমে সেই অনুপাতে ক্রপ করুন। 600 বাই 600 ক্রপ করে কমপ্রেস করলে চওড়া ছবি কমপ্রেস করে আশা করার চেয়ে পরিষ্কার ফল মেলে।</p>\n<h2 id=\"under-50kb-badge\">50KB-এর নিচে ব্যাজটি কীভাবে বুঝবেন</h2>\n<p>টুল শেষ হলে সফল ফলে 50KB-এর নিচে ব্যাজ দেখায়। এই ব্যাজই আপনার নিশ্চয়তা যে ফাইলটি পাস করেছে।</p>\n<p>ব্যাজটি শুধু তখনই দেখা যায় যখন চূড়ান্ত ফাইল বাইটে সীমার নিচে থাকে। সীমার কাছাকাছি কিন্তু উপরে থাকা ফাইলে এর বদলে সতর্কতা আসে।</p>\n<p>নিজের ডিভাইসের হিসাবের চেয়ে ব্যাজের উপর ভরসা করুন। বিভিন্ন সিস্টেম ফাইলের আকার ভিন্নভাবে গোল করে, আর টুল সঠিক বাইট সংখ্যা মাপে।</p>\n<p>লক্ষ্য মেলেনি সতর্কতা দেখলে টুল আপনার সঙ্গে সৎ থাকছে। এর মানে ছবিটি বর্তমান সেটিংসে 50KB-তে পৌঁছাতে পারেনি।</p>\n<p>লক্ষ্য না মেলা সেটিংসের সমস্যা, শেষ রাস্তা নয়। ফরম্যাট বদলান, স্কেলিংয়ের অনুমতি দিন বা আরও টাইট ক্রপ করুন, তারপর আবার চালান।</p>\n<h2 id=\"when-50kb-is-impossible\">যখন 50KB সত্যিই অসম্ভব</h2>\n<p>কিছু ছবি 50KB-তে না পৌঁছালে অকেজো হয়ে যায়। বিশজন মুখের ঘন গ্রুপ ছবি তার একটি উদাহরণ।</p>\n<p>নির্দিষ্ট মাপ বিষয়টি আরও কঠিন করে। পোর্টাল বড় পিক্সেল মাপ আর 50KB সীমা দুটোই চাইলে নিয়ম দুটি পরস্পরের সঙ্গে লড়তে পারে।</p>\n<p>ক্ষতিহীন PNG এটিকে সবচেয়ে কঠিন করে। PNG-তে আটকে থাকা বিস্তারিত ছবি যতই ছোট করুন না কেন, কখনোই আঁটতে পারে না।</p>\n<p>এমন ক্ষেত্রে যা নিয়ন্ত্রণে আছে তা বদলান। JPG-তে যান, ছবি আরও টাইট ক্রপ করুন, বা পোর্টাল অনুমতি দিলে মাপ কমান।</p>\n<p>কিছুই না হলে পোর্টালের নিয়ম আবার পড়ুন। কখনো সীমাটি প্রতিটি ফাইলের জন্য নয়, মোট আপলোডের জন্য হয়, বা অন্য ফরম্যাট গ্রহণ করা হয়।</p>\n<p>৫০KB-তে আনা অসম্ভব হয় যখন ছবিতে অনেক বিবরণ থাকে। গাছের পাতা বা ভিড়ের ছবি ৫০KB-তে আনা কঠিন। বিবরণ বেশি থাকলে ফাইল ছোট হয় না।</p>\n<p>৫০KB-তে আনা অসম্ভব হয় যখন পোর্টালের মাপ বড় চায়। ২০০০ পিক্সেলের ছবি ৫০KB-তে আনা কঠিন। মাপ বড় হলে ফাইল বড় হয়।</p>\n<p>৫০KB-তে আনা অসম্ভব হলে পোর্টালের নিয়ম আবার পড়ুন। হয়তো সীমা ৫০KB নয়, ২০০KB। ভুল সীমা ধরে চেষ্টা করলে সময় নষ্ট হয়।</p>\n<p>৫০KB-তে আনা অসম্ভব হলে ছবিটি সাদা-কালো করে দেখুন। রঙিন ছবির চেয়ে সাদা-কালো ছবি ছোট হয়। পোর্টালে রঙিন ছবি না চাইলে সাদা-কালো ব্যবহার করুন।</p>\n<p>৫০KB-তে আনা অসম্ভব হলে মূল ছবিটি আবার তুলুন। ভালো আলোয় তোলা নতুন ছবি সহজে ৫০KB-তে আসে। অন্ধকার ছবি সহজে ছোট হয় না।</p>\n<p>৫০KB-তে আনা অসম্ভব হলে WebP চেষ্টা করুন। WebP একই মান অনেক ছোট ফাইলে দেয়। পোর্টাল WebP নিলে সমস্যা মিটে যায়।</p>\n<p>৫০KB-তে আনা অসম্ভব হলে ছবি টাইট ক্রপ করুন। চারপাশের অপ্রয়োজনীয় জায়গা কাটলে ফাইল ছোট হয়। মুখের ছবিতে কাঁধ পর্যন্ত রাখুন।</p>\n<p>৫০KB-তে আনা অসম্ভব হলে পোর্টালের সাহায্য কেন্দ্রে যোগাযোগ করুন। সীমা নিয়ে প্রশ্ন থাকলে জিজ্ঞেস করুন। ভুল বুঝে ফরম পাঠাবেন না।</p>\n<p>৫০KB-তে আনা অসম্ভব হলে হতাশ হবেন না। বেশিরভাগ ছবি ৫০KB-তে আসে। ব্যতিক্রমী ছবিতে একটু বেশি চেষ্টা লাগে।</p>\n<h2 id=\"storing-compressed-files\">কমপ্রেস করা ফাইল সংরক্ষণ ও পুনরায় ব্যবহার</h2>\n<p>কমপ্রেস করা ফাইলগুলো গুছিয়ে রাখুন। আবেদনের নামে একটি ফোল্ডার, তার ভেতরে ছবি আর স্বাক্ষর রাখলে পরে বিভ্রান্তি হয় না।</p>\n<p>মূল ফাইলগুলো মুছবেন না। পোর্টালের নিয়ম বদলে যায়, আর 50KB-এর ফাইলকে আবার উচ্চ মানের মূলে ফেরানো যায় না।</p>\n<p>ফাইলের নাম উদ্দেশ্য অনুযায়ী দিন, তারিখ অনুযায়ী নয়। visa-photo-50kb.jpg নাম এক বছর পরেও কাজে লাগে; IMG_4821.jpg নাম লাগে না।</p>\n<p>সংরক্ষিত ফাইল পুনরায় ব্যবহারের আগে পরীক্ষা করুন। একবার খুলে দেখুন এখনো ঠিক দেখাচ্ছে কি না, তারপর নতুন ফরমে সংযুক্ত করুন।</p>\n<p>সবশেষে মনে রাখুন, প্রতিটি পোর্টাল আলাদা। এক পরীক্ষার বোর্ডের জন্য বানানো ফাইল আরেকটির জন্য নাও মিলতে পারে, তাই প্রতিটি আবেদনের জন্য নতুন করে কমপ্রেস করুন।</p>\n<h2 id=\"lighting-and-source-quality\">আলো ও মূল ছবির মান সেটিংসের চেয়ে গুরুত্বপূর্ণ</h2>\n<p>কোনো কমপ্রেসর খারাপ মূল ছবিকে বাঁচাতে পারে না। অন্ধকার, শব্দযুক্ত প্রতিকৃতি 50KB-তেও অন্ধকার আর শব্দযুক্তই থাকবে, শুধু ছোট হবে।</p>\n<p>ভালো আলো সবচেয়ে সস্তা কোয়ালিটি উন্নতি। জানালার পাশে তোলা ছবি হলুদ বাল্বের নিচে তোলা ছবিকে যেকোনো ফাইল আকারে ছাড়িয়ে যায়।</p>\n<p>ক্যামেরা স্থির রাখুন আর মুখে ফোকাস করতে দিন। ঝাপসা মূল ছবি কমপ্রেস হয়ে আরও ঝাপসা হয়, আর কোনো সেটিং তা ফেরাতে পারে না।</p>\n<p>পাসপোর্টের মতো ছবি তোলার আগে লেন্স মুছে নিন। ময়লা লেন্স এমন কুয়াশা যোগ করে যা মুখের বিবরণের বদলে কিলোবাইট নষ্ট করে।</p>\n<p>যখন উৎস আপনার নিয়ন্ত্রণে থাকে, ফরমের জন্য নতুন ছবি তুলুন। ভালো আলোয় পাঁচ মিনিট কমপ্রেশন সেটিংস নিয়ে এক ঘণ্টা লড়াই বাঁচিয়ে দেয়।</p>\n<h2 id=\"backgrounds-and-clothing\">ব্যাকগ্রাউন্ড, পোশাক ও কনট্রাস্ট</h2>\n<p>সাধারণ ব্যাকগ্রাউন্ড ব্যস্ত ব্যাকগ্রাউন্ডের চেয়ে অনেক ভালো কমপ্রেস হয়। ব্যাকগ্রাউন্ডের প্রতিটি পাতা, পোস্টার বা প্যাটার্ন কিলোবাইট খরচ করে যা মুখ ব্যবহার করতে পারত।</p>\n<p>পরিচয়পত্রের ছবির জন্য হালকা, খালি দেয়ালের সামনে দাঁড়ান। সাধারণ অংশ প্রায় কিছুই খরচ না করে কমপ্রেস হয়, বাজেটটা মুখের জন্য থাকে।</p>\n<p>পোশাকও গুরুত্বপূর্ণ। সূক্ষ্ম চেক প্যাটার্নের শার্ট সংরক্ষণে ব্যয়বহুল, আর একরঙা পোশাকে প্রায় কিছুই লাগে না।</p>\n<p>বিষয় আর ব্যাকগ্রাউন্ডের মধ্যে কনট্রাস্ট কমপ্রেসরকে সাহায্য করে। হালকা দেয়ালের সামনে গাঢ় চুলের মানুষ পরিষ্কারভাবে আলাদা হয়, এতে প্রান্ত পরিষ্কার থাকে।</p>\n<p>এই ছোট সিদ্ধান্তগুলো একসঙ্গে অনেক কিছু করে। একসঙ্গে এগুলোই 50KB-তে পরিষ্কার পাস আর লক্ষ্য না মেলার পার্থক্য গড়ে দিতে পারে।</p>\n<h2 id=\"retaking-vs-fixing\">আবার কমপ্রেস নয়, নতুন ছবি তুলুন কখন</h2>\n<p>কখনো সবচেয়ে দ্রুত সমাধান নতুন সেটিং নয়, নতুন ছবি। উৎস ঝাপসা, অন্ধকার বা খারাপভাবে ফ্রেম করা হলে কমপ্রেশন তা বাঁচাতে পারে না।</p>\n<p>মুখ ফোকাসের বাইরে থাকলে আবার ছবি তুলুন। কোনো কোয়ালিটি টিউনিং ঝাপসা চোখকে পরিষ্কার করে না।</p>\n<p>আলো খারাপ হলে আবার ছবি তুলুন। অর্ধেক ছায়ায় থাকা মুখ খারাপভাবে কমপ্রেস হয়, কারণ ছায়া এমন বিবরণ লুকায় যা টুল ফেরাতে পারে না।</p>\n<p>ফ্রেমিংয়ে জায়গা নষ্ট হলে আবার ছবি তুলুন। চওড়া শটে ছোট মুখ 50KB-তে কমপ্রেসরের কাজে প্রায় কিছুই দেয় না।</p>\n<p>দুই মিনিটের নতুন ছবি বিশ মিনিটের টিউনিংকে ছাড়িয়ে যায়। প্রথম চেষ্টাটি রেখে দিন, আরও ভালো ছবি তুলুন, আর সেটিই কমপ্রেস করুন।</p>\n<p>অন্য ফরমের জন্য ভিন্ন সীমা দরকার হলে <a href=\"/bn/image-100kb-te-compress-korun\">100KB কমপ্রেসর</a>, <a href=\"/bn/image-200kb-te-compress-korun\">200KB কমপ্রেসর</a> বা নির্দিষ্ট আকারের জন্য <a href=\"/bn/target-file-size-compressor\">টার্গেট ফাইল সাইজ কমপ্রেসর</a> ব্যবহার করুন। এই প্রক্রিয়ার ধাপে ধাপে সংস্করণের জন্য দেখুন <a href=\"/bn/blog/image-50kb-te-compress-kivabe-korben\">50KB-তে ছবি কমপ্রেস করবেন কীভাবে</a>।</p>\n";

export const FAQS: BlogArticleFaq[] = [{"question":"পাসপোর্ট আবেদনের জন্য 50KB-এর ছবি কি যথেষ্ট?","answer":"হ্যাঁ, যখন পোর্টাল নিজেই 50KB সীমা ঠিক করে দেয়। যেসব পোর্টাল 50KB চায়, সেগুলো এই আকারের ছবি পড়ার জন্যই তৈরি, আর ভালোভাবে কমপ্রেস করা JPG মুখ পরিষ্কার রাখে। পিক্সেলের মাপও পোর্টালের নিয়মের সঙ্গে মেলাতে হবে, কারণ আকার আর মাপ আলাদাভাবে পরীক্ষা করা হয়।"},{"question":"50KB-তে কমপ্রেস করার পর আমার ছবি নরম দেখাচ্ছে কেন?","answer":"এত ছোট আকারে পৌঁছাতে প্রচুর ডেটা সরাতে হয়, তাই নরমভাব আসে। মূল উচ্চ মানের ছবি দিয়ে শুরু করলে ভালো ফল মেলে, আর মাপ যতটা সম্ভব বড় রাখলেও সাহায্য হয়। ইতিমধ্যে কমপ্রেস করা কপি আবার কমপ্রেস করবেন না, কারণ প্রতিটি রাউন্ডে আরও নরমভাব বাড়ে।"},{"question":"আমি কি ফোনে ছবি 50KB-তে কমপ্রেস করতে পারব?","answer":"হ্যাঁ। টুলটি ফোন ও ট্যাবলেটের ব্রাউজারে চলে, আর কমপ্রেশন আপনার ডিভাইসেই হয়। গ্যালারি থেকে ছবি আপলোড করুন, ফলের জন্য অপেক্ষা করুন, দেখে নিন, তারপর কমপ্রেস করা কপি ডাউনলোড করুন।"},{"question":"আমার ছবি 50KB-এর নিচে না গেলে কী করব?","answer":"আউটপুট ফরম্যাট JPG বা WebP-তে বদলান, কারণ PNG ছবির ক্ষেত্রে 50KB-তে প্রায়ই আঁটে না। মাপ কমানোর অনুমতি দিন, যাতে টুল পিক্সেলের আকার কমাতে পারে। পোর্টাল নির্দিষ্ট মাপও চাইলে প্রথমে WebP, তারপর ছোট ক্রপসহ JPG চেষ্টা করুন।"},{"question":"50KB-তে কমপ্রেস করলে কি পিক্সেলের মাপ বদলে যায়?","answer":"সবসময় নয়। টুল প্রথমে পূর্ণ আকারে কোয়ালিটি কমিয়ে 50KB-তে পৌঁছানোর চেষ্টা করে। শুধু কোয়ালিটি দিয়ে লক্ষ্য না মিললেই মাপ কমায়। পোর্টালের নির্দিষ্ট মাপ দরকার হলে আপলোডের আগে ফলের মাপ পরীক্ষা করুন।"},{"question":"ব্রাউজার টুলে পাসপোর্ট ছবি কমপ্রেস করা কি নিরাপদ?","answer":"এই টুলে হ্যাঁ, কারণ সব প্রক্রিয়া আপনার ব্রাউজারে স্থানীয়ভাবে হয় আর কিছুই সার্ভারে আপলোড হয় না। কমপ্রেশনের সময় টুল GPS অবস্থানের ট্যাগও মুছে দেয়। পরিচয়পত্রের ছবি অজানা সার্ভারে আপলোড চায় এমন টুল এড়িয়ে চলুন।"}];
